plan = []; bad = 0
for f, x in F.items():
    p = f'{R}/{f}'; s = open(p, encoding='utf-8').read(); n = [s.count(a) for a, _ in x['A']]
    al = '2.99.578' in s; print(f, 'sha', sha(s), '(LAMWEB base', x['base'] + ')', 'anchors', *n, 'already', al)
    if al or n != [1] * len(n): bad = 1; continue
    t = s
    for a, b in x['A']: t = t.replace(a, b)
    plan.append((f, p, t))
if bad: sys.exit('STOP: an anchor is not found exactly once (or already patched) - nothing changed')
if not go:
    for f, p, t in plan: print('NEW would be', f, sha(t))
    sys.exit('check only - run again with: go')
bk = os.path.expanduser('~/app/old'); os.makedirs(bk, exist_ok=True); st = time.strftime('%m%d%H%M'); done = []
for f, p, t in plan:
    b = f'{bk}/' + os.path.basename(f) + f'.pre-578-{st}'; shutil.copy2(p, b); m = os.stat(p).st_mode; open(p, 'w', encoding='utf-8').write(t); os.chmod(p, m); done.append((p, b))
    chk = ['php', '-l', p] if p.endswith('.php') else (['node', '--check', p] if shutil.which('node') else None)
    if chk:
        r = subprocess.run(chk, capture_output=True, text=True)
        if r.returncode:
            for q, bb in done: shutil.copy2(bb, q)
            sys.exit('ERROR in ' + f + ' - every file put back: ' + (r.stdout + r.stderr)[:300])
    print('NEW', f, sha(t), 'backup', b)
